96: coap_pdu_t *
97: coap_pdu_init(coap_pdu_type_t type, coap_pdu_code_t code, coap_mid_t mid,
98:               size_t size) {
99:   coap_pdu_t *pdu;
100:

100: 
101: #ifndef RIOT_VERSION
102:   assert(type <= 0x3);
103:   assert(code <= 0xff);
104:   assert(mid >= 0 && mid <= 0xffff);
105: #endif /* RIOT_VERSION */
106: 
107: #ifdef WITH_LWIP
108: #if MEMP_STATS
109:   /* Reserve 1 PDU for a response packet */
110:   if (memp_pools[MEMP_COAP_PDU]->stats->used + 1 >=
111:       memp_pools[MEMP_COAP_PDU]->stats->avail) {
112:     memp_pools[MEMP_COAP_PDU]->stats->err++;
113:     return NULL;
114:   }
115: #endif /* MEMP_STATS */
116: #endif /* LWIP */
117:   pdu = coap_malloc_type(COAP_PDU, sizeof(coap_pdu_t));
118:   if (!pdu)
119:     return NULL;
120: 
121: #if defined(WITH_CONTIKI) || defined(WITH_LWIP)
122:   assert(size <= COAP_DEFAULT_MAX_PDU_RX_SIZE);
123:   if (size > COAP_DEFAULT_MAX_PDU_RX_SIZE)
124:     return NULL;
125:   pdu->max_hdr_size = COAP_PDU_MAX_UDP_HEADER_SIZE;
126: #else
127:   pdu->max_hdr_size = COAP_PDU_MAX_TCP_HEADER_SIZE;
128: #endif
129: 
130: #ifdef WITH_LWIP
131:   pdu->pbuf = pbuf_alloc(PBUF_TRANSPORT, size + pdu->max_hdr_size, PBUF_RAM);
132:   if (pdu->pbuf == NULL) {
133:     coap_free_type(COAP_PDU, pdu);
134:     return NULL;
135:   }
136:   pdu->token = (uint8_t *)pdu->pbuf->payload + pdu->max_hdr_size;
137: #else /* WITH_LWIP */
138:   uint8_t *buf;
139:   pdu->alloc_size = min(size, 256);
140:   buf = coap_malloc_type(COAP_PDU_BUF, pdu->alloc_size + pdu->max_hdr_size);
141:   if (buf == NULL) {
142:     coap_free_type(COAP_PDU, pdu);
143:     return NULL;
144:   }
145:   pdu->token = buf + pdu->max_hdr_size;
146: #endif /* WITH_LWIP */
147:   coap_pdu_clear(pdu, size);
148:   pdu->mid = mid;
149:   pdu->type = type;
150:   pdu->code = code;
151:   return pdu;
152: }
